#!/usr/bin/env node
/**
 * Copies the repository documents that the Developers pages render into a
 * TypeScript module, so the pages never read files at runtime: the
 * Markdown is part of the build like any other source.
 *
 *   node apps/web/scripts/generate-developer-docs.mjs          # rewrite the module
 *   node apps/web/scripts/generate-developer-docs.mjs --check  # exit 1 when it is stale
 *   pnpm --filter @lobbyforge/web docs:generate               # the same as the first
 *
 * The generated file is committed; `lib/developer-docs/__tests__/generated.test.ts`
 * fails while it differs from what this script would write, so a doc edit
 * without a regeneration cannot merge.
 *
 * To render another document, add it to DEVELOPER_DOC_SOURCES, run the
 * script, and give the slug its titles in `lib/developer-docs/registry.ts`
 * (the compiler insists) and in `messages/<code>/developers.json`.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

/** Page slug (`/developers/<slug>`) → repository file. Order is the section's order. */
export const DEVELOPER_DOC_SOURCES = [
  { slug: 'extending', path: 'docs/EXTENDING.md' },
  { slug: 'bots', path: 'docs/BOTS.md' },
  { slug: 'bot-api-v2', path: 'docs/BOT_API_V2.md' },
  { slug: 'plugins', path: 'docs/PLUGIN_SDK.md' },
  { slug: 'publishing', path: 'docs/PLUGIN_PUBLISHING.md' },
];

/** Where the module is written, relative to the repository root. */
export const GENERATED_MODULE_PATH = 'apps/web/lib/developer-docs/docs.generated.ts';

export const REPO_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '../../..');

/** Line endings as git stores them, whatever the checkout did. */
export function normalizeMarkdown(text) {
  return text.replace(/^﻿/, '').replace(/\r\n?/g, '\n');
}

/** A template literal holding `text` exactly. */
function templateLiteral(text) {
  return '`' + text.replace(/\\/g, '\\\\').replace(/`/g, '\\`').replace(/\$\{/g, '\\${') + '`';
}

export function buildDeveloperDocsModule(root = REPO_ROOT) {
  const entries = DEVELOPER_DOC_SOURCES.map(({ slug, path }) => {
    const markdown = normalizeMarkdown(readFileSync(join(root, path), 'utf8'));
    return `  ${JSON.stringify(slug)}: {\n    path: ${JSON.stringify(path)},\n    markdown: ${templateLiteral(markdown)},\n  },`;
  });
  return [
    '// Generated by apps/web/scripts/generate-developer-docs.mjs from the repository docs — do not edit.',
    '// Regenerate with `pnpm --filter @lobbyforge/web docs:generate`; a test fails while this is stale.',
    '',
    `export const DEVELOPER_DOC_SLUGS = [${DEVELOPER_DOC_SOURCES.map(({ slug }) => JSON.stringify(slug)).join(', ')}] as const;`,
    '',
    'export type DeveloperDocSlug = (typeof DEVELOPER_DOC_SLUGS)[number];',
    '',
    'export interface GeneratedDeveloperDoc {',
    '  /** The file in the repository, relative to its root. */',
    '  path: string;',
    '  /** Its Markdown, with LF line endings. */',
    '  markdown: string;',
    '}',
    '',
    'export const DEVELOPER_DOCS: Record<DeveloperDocSlug, GeneratedDeveloperDoc> = {',
    ...entries,
    '};',
    '',
  ].join('\n');
}

export function writeDeveloperDocsModule(root = REPO_ROOT) {
  const target = join(root, GENERATED_MODULE_PATH);
  const next = buildDeveloperDocsModule(root);
  let current = null;
  try {
    current = normalizeMarkdown(readFileSync(target, 'utf8'));
  } catch {
    current = null;
  }
  if (current === next) return { path: GENERATED_MODULE_PATH, changed: false };
  writeFileSync(target, next);
  return { path: GENERATED_MODULE_PATH, changed: true };
}

export function isDeveloperDocsModuleCurrent(root = REPO_ROOT) {
  try {
    return normalizeMarkdown(readFileSync(join(root, GENERATED_MODULE_PATH), 'utf8')) === buildDeveloperDocsModule(root);
  } catch {
    return false;
  }
}

const invokedDirectly = process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (invokedDirectly) {
  if (process.argv.includes('--check')) {
    if (isDeveloperDocsModuleCurrent()) {
      console.info(`${GENERATED_MODULE_PATH} is up to date.`);
    } else {
      console.error(`${GENERATED_MODULE_PATH} is stale. Run: pnpm --filter @lobbyforge/web docs:generate`);
      process.exitCode = 1;
    }
  } else {
    const { path, changed } = writeDeveloperDocsModule();
    console.info(changed ? `Wrote ${path}.` : `${path} is already up to date.`);
  }
}
